using System.Diagnostics;using System.IO;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Controls;using System.Windows.Input;
namespace SmartRAM;
public partial class StorageWindow:Window{
 CancellationTokenSource? cts;readonly ManualResetEventSlim pauseGate=new(true);StorageScanResult? result;List<FileRow> visible=new();DateTime scanStarted;DateTime lastProgress=DateTime.MinValue;string? lastViewKey;
 public StorageWindow(){InitializeComponent();DriveBox.ItemsSource=DriveInfo.GetDrives().Where(d=>d.IsReady).Select(d=>$"{d.Name}  {d.VolumeLabel}  {d.AvailableFreeSpace/1073741824d:F0} GB free").ToList();DriveBox.SelectedIndex=0;}
 string Root()=>DriveBox.SelectedItem?.ToString()?.Split(' ')[0]??"C:\\";
 async void Scan_Click(object s,RoutedEventArgs e){cts?.Cancel();cts=new();pauseGate.Set();PauseButton.Content="Pause";ScanProgressBar.Value=0;PercentText.Text="0%";scanStarted=DateTime.Now;lastProgress=DateTime.MinValue;Status.Text="Starting scan…";try{var cats=new HashSet<string>();if(VideosFilter.IsChecked==true)cats.Add("Videos");if(ImagesFilter.IsChecked==true)cats.Add("Images");if(AudioFilter.IsChecked==true)cats.Add("Audio");if(DocumentsFilter.IsChecked==true)cats.Add("Documents");if(ArchivesFilter.IsChecked==true)cats.Add("Archives");if(OtherFilter.IsChecked==true)cats.Add("Other");if(cats.Count==0){MessageBox.Show("Select at least one file type.");return;}if(!double.TryParse(MinSizeBox.Text,out var minMb)||minMb<0){MessageBox.Show("Minimum size must be zero or greater.");return;}var maxMb=string.IsNullOrWhiteSpace(MaxSizeBox.Text)?double.MaxValue:double.TryParse(MaxSizeBox.Text,out var mx)?mx:-1;if(maxMb<minMb){MessageBox.Show("Maximum size must be greater than or equal to minimum size.");return;}var progress=new Progress<ScanProgress>(p=>{if((DateTime.UtcNow-lastProgress).TotalMilliseconds<100&&p.Percent<100)return;lastProgress=DateTime.UtcNow;ScanProgressBar.Value=p.Percent;PercentText.Text=$"{p.Percent:F0}%";CurrentScanItem.Text=string.IsNullOrWhiteSpace(p.Current)?"":$"Now: {p.Current}";var elapsed=DateTime.Now-scanStarted;Status.Text=$"{p.Phase} · {p.Files:N0} files · {p.Bytes/1073741824d:F1} GB matched · {p.Folders:N0} folders · {p.Skipped:N0} skipped · {elapsed:mm\\:ss}";});lastViewKey=null;result=await StorageScanner.ScanAsync(Root(),progress,cts.Token,cats,(long)(minMb*1048576),maxMb==double.MaxValue?long.MaxValue:(long)(maxMb*1048576),pauseGate);SafeSummary.Text=$"Safe: {result.SafeBytes/1073741824d:F2} GB";DuplicateSummary.Text=$"Duplicate space: {result.DuplicateRecoverableBytes/1073741824d:F2} GB";ScanProgressBar.Value=100;PercentText.Text="100%";CurrentScanItem.Text="Scan complete — use the tabs below to review all files, largest files, duplicates, or safe cleanup.";Status.Text=$"Complete · {result.Files.Count:N0} files · {result.TotalBytes/1073741824d:F1} GB · {result.Skipped:N0} skipped";RefreshView();}catch(OperationCanceledException){Status.Text="Scan stopped safely.";}catch(Exception ex){Status.Text="Scan ended with an error.";MessageBox.Show(ex.Message,"RED RAM Storage Cleaner");}}
 void RefreshView(){if(result is null)return;var key=$"{ViewTabs.SelectedIndex}|{ShowKeepersCheck.IsChecked}|{SearchBox.Text?.Trim()}";if(key==lastViewKey&&FilesGrid.ItemsSource is not null)return;lastViewKey=key;IEnumerable<FileItem> q=result.Files;switch(ViewTabs.SelectedIndex){case 1:q=q.Where(x=>x.Category=="Videos");break;case 2:q=q.Where(x=>x.Category=="Images");break;case 3:q=q.Where(x=>x.Category=="Audio");break;case 4:q=q.Where(x=>x.Category=="Documents");break;case 5:q=q.Where(x=>x.Category=="Archives");break;case 6:q=q.Where(x=>x.Owner!=null||x.Ownership.StartsWith("Installed application"));break;case 7:q=q.Where(x=>x.DuplicateGroup!=null&&(ShowKeepersCheck.IsChecked==true||!x.DuplicateKeeper)).OrderBy(x=>x.DuplicateGroup).ThenBy(x=>x.DuplicateKeeper);break;case 8:q=q.Where(x=>x.SimilarGroup!=null).OrderBy(x=>x.SimilarGroup).ThenByDescending(x=>x.Similarity);break;case 9:q=q.Where(x=>x.Safety==FileSafety.SafeToClean&&!x.CloudOnly);break;}var find=SearchBox.Text?.Trim();if(!string.IsNullOrEmpty(find))q=q.Where(x=>x.Path.Contains(find,StringComparison.OrdinalIgnoreCase)||(x.Owner?.Contains(find,StringComparison.OrdinalIgnoreCase)??false));visible=q.OrderByDescending(x=>x.Bytes).Select(x=>new FileRow(x)).ToList();FilesGrid.ItemsSource=visible;}
 void ViewTabs_Changed(object s,SelectionChangedEventArgs e){if(IsLoaded){lastViewKey=null;RefreshView();}}void KeeperView_Changed(object s,RoutedEventArgs e){if(IsLoaded){lastViewKey=null;RefreshView();}}void ViewMode_Changed(object s,SelectionChangedEventArgs e){if(FilesGrid is null||ViewModeBox?.SelectedItem is not ComboBoxItem i)return;FilesGrid.RowHeight=i.Content?.ToString()=="Compact"?24:Double.NaN;}async void Search_Changed(object s,TextChangedEventArgs e){if(!IsLoaded)return;var text=SearchBox.Text;await Task.Delay(250);if(SearchBox.Text==text){lastViewKey=null;RefreshView();}}
 void SizePreset_Changed(object s,SelectionChangedEventArgs e){if(MinSizeBox is null||MaxSizeBox is null||SizePresetBox.SelectedItem is not ComboBoxItem i)return;var custom=(i.Content?.ToString()=="Custom");MinSizeBox.IsEnabled=custom;MaxSizeBox.IsEnabled=custom;switch(i.Content?.ToString()){case "Under 10 MB":MinSizeBox.Text="0";MaxSizeBox.Text="10";break;case "10–100 MB":MinSizeBox.Text="10";MaxSizeBox.Text="100";break;case "100–500 MB":MinSizeBox.Text="100";MaxSizeBox.Text="500";break;case "500 MB–1 GB":MinSizeBox.Text="500";MaxSizeBox.Text="1024";break;case "1–5 GB":MinSizeBox.Text="1024";MaxSizeBox.Text="5120";break;case "5–10 GB":MinSizeBox.Text="5120";MaxSizeBox.Text="10240";break;case "10 GB+":MinSizeBox.Text="10240";MaxSizeBox.Text="";break;case "Any size":MinSizeBox.Text="0";MaxSizeBox.Text="";break;case "Custom":if(string.IsNullOrWhiteSpace(MinSizeBox.Text))MinSizeBox.Text="0";break;}}
 void Pause_Click(object s,RoutedEventArgs e){if(pauseGate.IsSet){pauseGate.Reset();PauseButton.Content="Resume";Status.Text="Scan paused.";}else{pauseGate.Set();PauseButton.Content="Pause";Status.Text="Resuming…";}}void Stop_Click(object s,RoutedEventArgs e){pauseGate.Set();cts?.Cancel();}void SelectVisible_Click(object s,RoutedEventArgs e){foreach(var x in visible.Where(x=>x.Item.Safety!=FileSafety.Protected&&!x.Item.CloudOnly&&!x.Item.DuplicateKeeper))x.Selected=true;FilesGrid.Items.Refresh();}void ClearSelection_Click(object s,RoutedEventArgs e){foreach(var x in visible)x.Selected=false;FilesGrid.Items.Refresh();}
 FileRow? Current()=>FilesGrid.SelectedItem as FileRow;void FilesGrid_DoubleClick(object s,MouseButtonEventArgs e){Open(Current());}void OpenFile_Click(object s,RoutedEventArgs e)=>Open(Current());void Open(FileRow? r){if(r is null)return;if(r.Item.CloudOnly&&MessageBox.Show("This is a cloud-only file. Opening it may download it from OneDrive. Continue?","Cloud file",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;try{Process.Start(new ProcessStartInfo(r.Item.Path){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(ex.Message);}}
 void Explorer_Click(object s,RoutedEventArgs e){var r=Current();if(r is null)return;try{Process.Start(new ProcessStartInfo("explorer.exe",$"/select,\"{r.Item.Path}\""){UseShellExecute=true});}catch(Exception ex){MessageBox.Show(ex.Message);}}void Properties_Click(object s,RoutedEventArgs e){var r=Current();if(r is null)return;try{var sei=new SHELLEXECUTEINFO{cbSize=Marshal.SizeOf<SHELLEXECUTEINFO>(),lpVerb="properties",lpFile=r.Item.Path,nShow=1,fMask=0x0000000C};ShellExecuteEx(ref sei);}catch(Exception ex){MessageBox.Show(ex.Message);}}void CopyPath_Click(object s,RoutedEventArgs e){var r=Current();if(r!=null)Clipboard.SetText(r.Item.Path);}
 void CleanSafe_Click(object s,RoutedEventArgs e){if(result is null)return;DeleteItems(result.Files.Where(x=>x.Safety==FileSafety.SafeToClean&&!x.CloudOnly).ToList(),"safe cleanup");}void Delete_Click(object s,RoutedEventArgs e)=>DeleteItems(visible.Where(x=>x.Selected).Select(x=>x.Item).ToList(),"selected");
 void SaveCleanupReport(int moved,int skipped,int failed,long bytes,string label,List<string> skippedPaths){try{var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"RED RAM","History");Directory.CreateDirectory(dir);var path=Path.Combine(dir,$"cleanup-{DateTime.Now:yyyyMMdd-HHmmss}.txt");File.WriteAllLines(path,new[]{$"RED RAM cleanup report — {DateTime.Now:g}",$"Mode: {label}",$"Moved to Recycle Bin: {moved}",$"Skipped: {skipped}",$"Failed: {failed}",$"Bytes moved to Recycle Bin: {bytes}", "", "Skipped/failed paths:"}.Concat(skippedPaths));}catch{}}
 void DeleteItems(List<FileItem> items,string label){var allowed=items.Where(StorageScanner.CanDelete).ToList();if(allowed.Count==0){MessageBox.Show("Select deletable files first.");return;}var cloud=allowed.Count(x=>x.CloudOnly);var duplicateGroups=allowed.Where(x=>x.DuplicateGroup!=null).GroupBy(x=>x.DuplicateGroup).ToList();foreach(var g in duplicateGroups){var all=result!.Files.Count(x=>x.DuplicateGroup==g.Key);if(g.Count()>=all){var keep=g.OrderBy(x=>x.ModifiedAt).First();allowed.Remove(keep);}}if(allowed.Count==0){MessageBox.Show("RED RAM kept one copy from each duplicate group. Nothing remains selected for deletion.");return;}var bytes=allowed.Sum(x=>x.Bytes);var warning=cloud>0?$"\n\nWarning: {cloud} selected cloud-synced file(s) may also be removed from OneDrive and synced devices.":"";if(MessageBox.Show($"Move {allowed.Count:N0} {label} file(s) ({bytes/1073741824d:F2} GB) to the Recycle Bin?{warning}","RED RAM Storage Cleaner",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;int ok=0,failed=0,skipped=0;long movedBytes=0;var skippedPaths=new List<string>();bool skipAllFailures=false;foreach(var i in allowed){try{StorageScanner.DeleteToRecycleBin(i);ok++;movedBytes+=i.Bytes;}catch(Exception ex){failed++;if(skipAllFailures){skipped++;skippedPaths.Add(i.Path);continue;}var choice=MessageBox.Show($"Windows could not delete:\n{Path.GetFileName(i.Path)}\n\n{ex.Message}\n\nYes = Skip this file\nNo = Skip all files that cannot be deleted\nCancel = Stop cleanup","File could not be deleted",MessageBoxButton.YesNoCancel,MessageBoxImage.Warning);if(choice==MessageBoxResult.Yes){skipped++;skippedPaths.Add(i.Path);continue;}if(choice==MessageBoxResult.No){skipAllFailures=true;skipped++;skippedPaths.Add(i.Path);continue;}skippedPaths.Add(i.Path);break;}}SaveCleanupReport(ok,skipped,failed,movedBytes,label,skippedPaths);Status.Text=$"Moved {ok:N0} file(s) to Recycle Bin"+(skipped>0?$"; {skipped:N0} locked/protected file(s) skipped":"")+(failed>skipped?$"; {failed-skipped:N0} failed":"")+". Rescan to refresh.";}
 class FileRow{public FileItem Item{get;}public bool Selected{get;set;}public string Name=>Path.GetFileName(Item.Path);public string Folder=>Path.GetDirectoryName(Item.Path)??"";public string Size=>Item.Bytes>=1073741824?$"{Item.Bytes/1073741824d:F2} GB":$"{Item.Bytes/1048576d:F1} MB";public string Type=>string.IsNullOrWhiteSpace(Item.Extension)?"File":Item.Extension;public string Owner=>Item.Owner??Item.Ownership;public FileSafety Safety=>Item.Safety;public string Status=>Item.DuplicateKeeper?"Protected copy kept by RED RAM":Item.DuplicateGroup!=null?"Duplicate copy":Item.CloudOnly?"Cloud file":Item.Reason;public DateTime ModifiedAt=>Item.ModifiedAt;public string Duplicate=>Item.CloudOnly?"Cloud":Item.DuplicateGroup??"";public string Similar=>Item.SimilarGroup is null?"":$"{Item.Similarity}% · {Item.SimilarGroup}";public FileRow(FileItem i){Item=i;}}
 protected override void OnClosed(EventArgs e){pauseGate.Set();cts?.Cancel();cts?.Dispose();pauseGate.Dispose();base.OnClosed(e);}
 [DllImport("shell32.dll",CharSet=CharSet.Unicode)]static extern bool ShellExecuteEx(ref SHELLEXECUTEINFO lpExecInfo);[StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct SHELLEXECUTEINFO{public int cbSize;public uint fMask;public IntPtr hwnd;[MarshalAs(UnmanagedType.LPWStr)]public string? lpVerb;[MarshalAs(UnmanagedType.LPWStr)]public string? lpFile;[MarshalAs(UnmanagedType.LPWStr)]public string? lpParameters;[MarshalAs(UnmanagedType.LPWStr)]public string? lpDirectory;public int nShow;public IntPtr hInstApp;public IntPtr lpIDList;[MarshalAs(UnmanagedType.LPWStr)]public string? lpClass;public IntPtr hkeyClass;public uint dwHotKey;public IntPtr hIcon;public IntPtr hProcess;}
